      data-testid={testId}
    >
      <div className="chat-message__bubble">
        {message.content}
        {message.imageSrc ? (
          <img
            className="chat-message__media"
            src={message.imageSrc}
            alt="General Grievous reaction"
            data-testid={
              message.role === 'assistant' ? 'message-assistant-image' : undefined
            }
          />
        ) : null}
      </div>
