// Strict origin guard helper (no URL constructor available in the CLI sandbox).
const ALLOWED_AUTHORITIES = new Set(['localhost:5174', '127.0.0.1:5174', '[::1]:5174']);

function classify(rawUrl) {
  const m = /^([a-zA-Z][a-zA-Z0-9+.\-]*):\/\/([^/?#]*)([^?#]*)/.exec(rawUrl);
  if (!m) return { ok: false, why: 'unparseable', label: rawUrl };
  const scheme = m[1].toLowerCase();
  const authority = m[2];
  const path = m[3] || '/';
  if (scheme !== 'http' && scheme !== 'https') return { ok: false, why: 'scheme', label: scheme + '://' + authority + path };
  if (authority.includes('@')) return { ok: false, why: 'credentials', label: scheme + '://<redacted>' + path };
  const authLower = authority.toLowerCase();
  if (!ALLOWED_AUTHORITIES.has(authLower)) return { ok: false, why: 'off-origin', label: scheme + '://' + authLower + path };
  if (scheme !== 'http') return { ok: false, why: 'scheme-origin-mismatch', label: scheme + '://' + authLower + path };
  return { ok: true, why: 'approved', label: scheme + '://' + authLower + path };
}

async function installGuard(page) {
  await page.context().unrouteAll({ behavior: 'ignoreErrors' });
  const blocked = [];
  const allowed = [];
  await page.context().route('**/*', async (route) => {
    const verdict = classify(route.request().url());
    if (!verdict.ok) { blocked.push(verdict.why + ' :: ' + verdict.label); return route.abort(); }
    allowed.push(verdict.label);
    return route.continue();
  });
  return { blocked, allowed };
}

function assertFinalOrigin(page) {
  const v = classify(page.url());
  if (!v.ok) throw new Error('final URL outside approved origin: ' + v.why + ' ' + v.label);
  return page.url();
}
