    // Settled state: the pending placeholder is gone, so the assertions below
    // read the real reply rather than the "Thinking…" bubble.
    await expect(chat.loadingIndicator).toHaveCount(0)
    await expect(chat.funnyModeCheckbox).toBeEnabled()

    // The array form pins the whole transcript: exactly one bubble on each
    // side, each with exactly this text.
    await expect(chat.userMessages).toHaveText([MESSAGE])
